1	/**
2	 * G1 — ties the external data shape to the rendered props.
3	 *
4	 * Every assertion below uses a value unique to its own field, so a mapping that reads the
5	 * wrong key fails rather than coincidentally matching. That is the whole point: the failure
6	 * mode this guards is a field quietly resolving to `undefined` and its line disappearing.
7	 */
8	import { describe, expect, test, vi } from 'vitest';
9	import { selectPdpProductInfo, buildRelatedSwatches, type PdpSourceProduct, type PdpSourcePrice, type RelatedSwatch } from './productInfo';
10	
11	/** Distinct sentinel per field — no two share a value. */
12	const FULL: PdpSourceProduct = {
13	  id: 'VARIANT-SKU-0001',
14	  name: 'Natura Mini Dress',
15	  longDescription: '<p>A long sleeve linen mini dress.</p>',
16	  master: { masterId: 'MASTER-STYLE-8637' },
17	  c_modelFit: 'Model is 178cm and wears a size 0',
18	  c_careInstructions: '<ul><li>Dry clean only</li></ul>',
19	  c_color: 'GVSCP',
20	  c_colourId: 'COLOUR-ID-42',
21	  c_environmentalNotes: 'Made with recycled fibres',
22	  c_fabricComposition: '100% silk habutae',
23	  c_hsCode: '6204.49',
24	  c_sizeFit: 'True to size, fitted through the bodice',
25	  c_styleId: 'STYLE-ID-99',
26	  c_styleNumber: 'STYLE-NUMBER-7300',
27	  c_stylingNotes: 'Style with the matching sandal',
28	  c_tabDescription: { markup: '<p>Tab description markup</p>', source: 'Tab description source' },
29	  c_tabDetails: { markup: '<p>Tab details markup</p>', source: 'Tab details source' },
30	};
31	
32	const formatPrice = (amount: number, currency: string) => `${currency} ${amount.toFixed(2)}`;
33	const map = (product: PdpSourceProduct | null | undefined, price: PdpSourcePrice | null = { currentPrice: 895 }) =>
34	  selectPdpProductInfo(product, price, 'AUD', formatPrice);
35	
36	describe('selectPdpProductInfo — every field reaches the right prop', () => {
37	  test.each`
38	    prop                    | source                       | expected
39	    ${'name'}               | ${'name'}                    | ${'Natura Mini Dress'}
40	    ${'description'}        | ${'longDescription'}         | ${'<p>A long sleeve linen mini dress.</p>'}
41	    ${'modelInfo'}          | ${'c_modelFit'}              | ${'Model is 178cm and wears a size 0'}
42	    ${'careInstructions'}   | ${'c_careInstructions'}      | ${'<ul><li>Dry clean only</li></ul>'}
43	    ${'styleCode'}          | ${'master.masterId'}         | ${'MASTER-STYLE-8637'}
44	    ${'price'}              | ${'priceData.currentPrice'}  | ${'AUD 895.00'}
45	    ${'colour'}             | ${'c_color'}                 | ${'GVSCP'}
46	    ${'colourId'}           | ${'c_colourId'}              | ${'COLOUR-ID-42'}
47	    ${'environmentalNotes'} | ${'c_environmentalNotes'}    | ${'Made with recycled fibres'}
48	    ${'fabricComposition'}  | ${'c_fabricComposition'}     | ${'100% silk habutae'}
49	    ${'hsCode'}             | ${'c_hsCode'}                | ${'6204.49'}
50	    ${'sizeFit'}            | ${'c_sizeFit'}               | ${'True to size, fitted through the bodice'}
51	    ${'styleId'}            | ${'c_styleId'}               | ${'STYLE-ID-99'}
52	    ${'styleNumber'}        | ${'c_styleNumber'}           | ${'STYLE-NUMBER-7300'}
53	    ${'stylingNotes'}       | ${'c_stylingNotes'}          | ${'Style with the matching sandal'}
54	    ${'tabDescription'}     | ${'c_tabDescription.markup'} | ${'<p>Tab description markup</p>'}
55	    ${'tabDetails'}         | ${'c_tabDetails.markup'}     | ${'<p>Tab details markup</p>'}
56	  `('$prop <- $source', ({ prop, expected }) => {
57	    expect(map(FULL)?.[prop as keyof ReturnType<typeof map> & string]).toBe(expected);
58	  });
59	
60	  test('styleCode is the master style number, not the variant id', () => {
61	    // The regression this pins: after the first swatch click `product.id` becomes the variant
62	    // SKU while the style code shown to shoppers must not change.
63	    expect(map(FULL)?.styleCode).toBe('MASTER-STYLE-8637');
64	    expect(map(FULL)?.styleCode).not.toBe(FULL.id);
65	  });
66	
67	  test('falls back to product.id for a standard product with no master', () => {
68	    expect(map({ ...FULL, master: undefined })?.styleCode).toBe('VARIANT-SKU-0001');
69	  });
70	});
71	
72	describe('selectPdpProductInfo — absent fields', () => {
73	  test.each(['longDescription', 'c_modelFit', 'c_careInstructions', 'master'] as const)(
74	    'a missing %s yields undefined, not a blank string',
75	    (field) => {
76	      const info = map({ ...FULL, [field]: undefined });
77	      expect(info).not.toBeNull();
78	      // `undefined` matters: the atoms branch on it to render nothing at all. An empty string
79	      // would still be truthy at some call sites and could render an empty styled node.
80	      const byField = {
81	        longDescription: 'description',
82	        c_modelFit: 'modelInfo',
83	        c_careInstructions: 'careInstructions',
84	        master: 'styleCode',
85	      } as const;
86	      if (field !== 'master') expect(info?.[byField[field]]).toBeUndefined();
87	    },
88	  );
89	
90	  test('only name is load-bearing — no name means nothing to render yet', () => {
91	    expect(map(undefined)).toBeNull();
92	    expect(map(null)).toBeNull();
93	    expect(map({ ...FULL, name: undefined })).toBeNull();
94	    expect(map({ ...FULL, name: '' })).toBeNull();
95	  });
96	
97	  test('an absent price renders empty rather than "NaN" or "undefined"', () => {
98	    expect(map(FULL, null)?.price).toBe('');
99	    expect(map(FULL, {})?.price).toBe('');
100	    expect(map(FULL, { currentPrice: undefined })?.price).toBe('');
101	  });
102	
103	  test('a genuine zero price is formatted, not treated as absent', () => {
104	    expect(map(FULL, { currentPrice: 0 })?.price).toBe('AUD 0.00');
105	  });
106	});
107	
108	describe('selectPdpProductInfo — formatting is delegated', () => {
109	  test('calls the injected formatter once with the storefront currency', () => {
110	    const spy = vi.fn(() => '$895.00');
111	    selectPdpProductInfo(FULL, { currentPrice: 895 }, 'AUD', spy);
112	    expect(spy).toHaveBeenCalledOnce();
113	    expect(spy).toHaveBeenCalledWith(895, 'AUD');
114	  });
115	
116	  test('does no formatting of its own', () => {
117	    // Guards against a future edit reintroducing a hardcoded symbol or locale here; currency
118	    // presentation differs across the 8 storefronts and belongs to react-intl.
119	    expect(selectPdpProductInfo(FULL, { currentPrice: 895 }, 'HKD', (a, c) => `${c}${a}`)?.price).toBe('HKD895');
120	  });
121	});
122	
123	// ---------------------------------------------------------------------------
124	// PRC-09 — Was/Now sale price (SFCC-194)
125	// ---------------------------------------------------------------------------
126	
127	describe('selectPdpProductInfo — wasPrice (PRC-09)', () => {
128	  const mapSale = (priceData: Parameters<typeof map>[1]) => map(FULL, priceData);
129	
130	  // AC1: sale active — wasPrice is the formatted listPrice
131	  test('returns wasPrice when isOnSale is true and listPrice is a number', () => {
132	    const info = mapSale({ currentPrice: 450, isOnSale: true, listPrice: 595 });
133	    expect(info?.wasPrice).toBe('AUD 595.00');
134	    expect(info?.price).toBe('AUD 450.00');
135	  });
136	
137	  // AC2: no sale — wasPrice is absent
138	  test('returns undefined wasPrice when isOnSale is false', () => {
139	    const info = mapSale({ currentPrice: 595, isOnSale: false, listPrice: 595 });
140	    expect(info?.wasPrice).toBeUndefined();
141	  });
142	
143	  // AC2: standard product (no priceData sale fields) — wasPrice is absent
144	  test('returns undefined wasPrice when isOnSale is absent', () => {
145	    const info = mapSale({ currentPrice: 595 });
146	    expect(info?.wasPrice).toBeUndefined();
147	  });
148	
149	  // AC4: sale expired — listPrice removed or equal to currentPrice, isOnSale becomes false
150	  test('returns undefined wasPrice when isOnSale is true but listPrice is absent', () => {
151	    // BM can mark isOnSale:true but provide no listPrice; the atom must not render "Was undefined"
152	    const info = mapSale({ currentPrice: 450, isOnSale: true, listPrice: undefined });
153	    expect(info?.wasPrice).toBeUndefined();
154	  });
155	
156	  // isRange guard: colour-only selection where sizes have different sale prices
157	  test('returns undefined wasPrice when isRange is true even if isOnSale and listPrice are present', () => {
158	    // currentPrice is the cheapest variant's price — not a definite settled figure.
159	    // Showing "Was $795 Now $595" would misrepresent the full colourway's pricing.
160	    const info = mapSale({ currentPrice: 595, isOnSale: true, listPrice: 795, isRange: true });
161	    expect(info?.wasPrice).toBeUndefined();
162	    // The selling price itself is still shown — only the Was/Now pair is suppressed.
163	    expect(info?.price).toBe('AUD 595.00');
164	  });
165	
166	  // AC5: sale flagged but currentPrice absent — wasPrice must not appear without a paired Now
167	  test('returns undefined wasPrice when isOnSale and listPrice are present but currentPrice is absent', () => {
168	    // getPriceData (external, untyped) can return isOnSale:true with no currentPrice in edge
169	    // cases. Without this guard the mapper would emit wasPrice without a matching price, and
170	    // any future consumer that doesn't also check currentPrice would render "Was $595" alone.
171	    const info = mapSale({ isOnSale: true, listPrice: 595, currentPrice: undefined });
172	    expect(info?.wasPrice).toBeUndefined();
173	    // price itself is also absent — confirmed by the existing absent-price test above
174	    expect(info?.price).toBe('');
175	  });
176	
177	  test('returns wasPrice when isRange is false (definite single-variant price)', () => {
178	    const info = mapSale({ currentPrice: 595, isOnSale: true, listPrice: 795, isRange: false });
179	    expect(info?.wasPrice).toBe('AUD 795.00');
180	  });
181	
182	  // Formatter is called for wasPrice with the same currency as price
183	  test('formats wasPrice with the same injected formatter and currency as price', () => {
184	    const spy = vi.fn((amount: number, currency: string) => `${currency}${amount}`);
185	    selectPdpProductInfo(FULL, { currentPrice: 450, isOnSale: true, listPrice: 595 }, 'AUD', spy);
186	    expect(spy).toHaveBeenCalledTimes(2);
187	    expect(spy).toHaveBeenCalledWith(595, 'AUD');
188	  });
189	});
190	
191	// ---------------------------------------------------------------------------
192	// SFCC-708 — buildRelatedSwatches
193	// ---------------------------------------------------------------------------
194	
195	const urlBuilder = ({ id }: { id: string }) => `/product/${id}`;
196	const COLOUR_ATTR = 'color';
197	
198	const swatch = (over: Partial<RelatedSwatch> = {}): RelatedSwatch => ({
199	  masterProductID: 'MASTER-001',
200	  colourValue: 'IVORY',
201	  displayName: 'Ivory',
202	  swatchImageURL: 'https://example.test/swatch.jpg',
203	  ...over,
204	});
205	
206	describe('buildRelatedSwatches — field mapping', () => {
207	  test('maps displayName → name, swatchImageURL → imageUrl, masterProductID → value', () => {
208	    const [result] = buildRelatedSwatches(
209	      [swatch({ masterProductID: 'MASTER-002', displayName: 'Bay Blue', swatchImageURL: 'https://example.test/navy.jpg' })],
210	      urlBuilder,
211	      COLOUR_ATTR,
212	    );
213	    expect(result.name).toBe('Bay Blue');
214	    expect(result.imageUrl).toBe('https://example.test/navy.jpg');
215	    expect(result.value).toBe('MASTER-002');
216	  });
217	
218	  test('sets orderable: true and forceReload: true on every entry', () => {
219	    const [result] = buildRelatedSwatches([swatch()], urlBuilder, COLOUR_ATTR);
220	    expect(result.orderable).toBe(true);
221	    expect(result.forceReload).toBe(true);
222	  });
223	});
224	
