/**
 * G1 — ties the external data shape to the rendered props.
 *
 * Every assertion below uses a value unique to its own field, so a mapping that reads the
 * wrong key fails rather than coincidentally matching. That is the whole point: the failure
 * mode this guards is a field quietly resolving to `undefined` and its line disappearing.
 */
import { describe, expect, test, vi } from 'vitest';
import { selectPdpProductInfo, buildRelatedSwatches, type PdpSourceProduct, type PdpSourcePrice, type RelatedSwatch } from './productInfo';

/** Distinct sentinel per field — no two share a value. */
const FULL: PdpSourceProduct = {
  id: 'VARIANT-SKU-0001',
  name: 'Natura Mini Dress',
  longDescription: '<p>A long sleeve linen mini dress.</p>',
  master: { masterId: 'MASTER-STYLE-8637' },
  c_modelFit: 'Model is 178cm and wears a size 0',
  c_careInstructions: '<ul><li>Dry clean only</li></ul>',
  c_color: 'GVSCP',
  c_colourId: 'COLOUR-ID-42',
  c_environmentalNotes: 'Made with recycled fibres',
  c_fabricComposition: '100% silk habutae',
  c_hsCode: '6204.49',
  c_sizeFit: 'True to size, fitted through the bodice',
  c_styleId: 'STYLE-ID-99',
  c_styleNumber: 'STYLE-NUMBER-7300',
  c_stylingNotes: 'Style with the matching sandal',
  c_tabDescription: { markup: '<p>Tab description markup</p>', source: 'Tab description source' },
  c_tabDetails: { markup: '<p>Tab details markup</p>', source: 'Tab details source' },
};

const formatPrice = (amount: number, currency: string) => `${currency} ${amount.toFixed(2)}`;
const map = (product: PdpSourceProduct | null | undefined, price: PdpSourcePrice | null = { currentPrice: 895 }) =>
  selectPdpProductInfo(product, price, 'AUD', formatPrice);

describe('selectPdpProductInfo — every field reaches the right prop', () => {
  test.each`
    prop                    | source                       | expected
    ${'name'}               | ${'name'}                    | ${'Natura Mini Dress'}
    ${'description'}        | ${'longDescription'}         | ${'<p>A long sleeve linen mini dress.</p>'}
    ${'modelInfo'}          | ${'c_modelFit'}              | ${'Model is 178cm and wears a size 0'}
    ${'careInstructions'}   | ${'c_careInstructions'}      | ${'<ul><li>Dry clean only</li></ul>'}
    ${'styleCode'}          | ${'master.masterId'}         | ${'MASTER-STYLE-8637'}
    ${'price'}              | ${'priceData.currentPrice'}  | ${'AUD 895.00'}
    ${'colour'}             | ${'c_color'}                 | ${'GVSCP'}
    ${'colourId'}           | ${'c_colourId'}              | ${'COLOUR-ID-42'}
    ${'environmentalNotes'} | ${'c_environmentalNotes'}    | ${'Made with recycled fibres'}
    ${'fabricComposition'}  | ${'c_fabricComposition'}     | ${'100% silk habutae'}
    ${'hsCode'}             | ${'c_hsCode'}                | ${'6204.49'}
    ${'sizeFit'}            | ${'c_sizeFit'}               | ${'True to size, fitted through the bodice'}
    ${'styleId'}            | ${'c_styleId'}               | ${'STYLE-ID-99'}
    ${'styleNumber'}        | ${'c_styleNumber'}           | ${'STYLE-NUMBER-7300'}
    ${'stylingNotes'}       | ${'c_stylingNotes'}          | ${'Style with the matching sandal'}
    ${'tabDescription'}     | ${'c_tabDescription.markup'} | ${'<p>Tab description markup</p>'}
    ${'tabDetails'}         | ${'c_tabDetails.markup'}     | ${'<p>Tab details markup</p>'}
  `('$prop <- $source', ({ prop, expected }) => {
    expect(map(FULL)?.[prop as keyof ReturnType<typeof map> & string]).toBe(expected);
  });

  test('styleCode is the master style number, not the variant id', () => {
    // The regression this pins: after the first swatch click `product.id` becomes the variant
    // SKU while the style code shown to shoppers must not change.
    expect(map(FULL)?.styleCode).toBe('MASTER-STYLE-8637');
    expect(map(FULL)?.styleCode).not.toBe(FULL.id);
  });

  test('falls back to product.id for a standard product with no master', () => {
    expect(map({ ...FULL, master: undefined })?.styleCode).toBe('VARIANT-SKU-0001');
  });
});

describe('selectPdpProductInfo — absent fields', () => {
  test.each(['longDescription', 'c_modelFit', 'c_careInstructions', 'master'] as const)(
    'a missing %s yields undefined, not a blank string',
    (field) => {
      const info = map({ ...FULL, [field]: undefined });
      expect(info).not.toBeNull();
      // `undefined` matters: the atoms branch on it to render nothing at all. An empty string
      // would still be truthy at some call sites and could render an empty styled node.
      const byField = {
        longDescription: 'description',
        c_modelFit: 'modelInfo',
        c_careInstructions: 'careInstructions',
        master: 'styleCode',
      } as const;
      if (field !== 'master') expect(info?.[byField[field]]).toBeUndefined();
    },
  );

  test('only name is load-bearing — no name means nothing to render yet', () => {
    expect(map(undefined)).toBeNull();
    expect(map(null)).toBeNull();
    expect(map({ ...FULL, name: undefined })).toBeNull();
    expect(map({ ...FULL, name: '' })).toBeNull();
  });

  test('an absent price renders empty rather than "NaN" or "undefined"', () => {
    expect(map(FULL, null)?.price).toBe('');
    expect(map(FULL, {})?.price).toBe('');
    expect(map(FULL, { currentPrice: undefined })?.price).toBe('');
  });

  test('a genuine zero price is formatted, not treated as absent', () => {
    expect(map(FULL, { currentPrice: 0 })?.price).toBe('AUD 0.00');
  });
});

describe('selectPdpProductInfo — formatting is delegated', () => {
  test('calls the injected formatter once with the storefront currency', () => {
    const spy = vi.fn(() => '$895.00');
    selectPdpProductInfo(FULL, { currentPrice: 895 }, 'AUD', spy);
    expect(spy).toHaveBeenCalledOnce();
    expect(spy).toHaveBeenCalledWith(895, 'AUD');
  });

  test('does no formatting of its own', () => {
    // Guards against a future edit reintroducing a hardcoded symbol or locale here; currency
    // presentation differs across the 8 storefronts and belongs to react-intl.
    expect(selectPdpProductInfo(FULL, { currentPrice: 895 }, 'HKD', (a, c) => `${c}${a}`)?.price).toBe('HKD895');
  });
});

// ---------------------------------------------------------------------------
// PRC-09 — Was/Now sale price (SFCC-194)
// ---------------------------------------------------------------------------

describe('selectPdpProductInfo — wasPrice (PRC-09)', () => {
  const mapSale = (priceData: Parameters<typeof map>[1]) => map(FULL, priceData);

  // AC1: sale active — wasPrice is the formatted listPrice
  test('returns wasPrice when isOnSale is true and listPrice is a number', () => {
    const info = mapSale({ currentPrice: 450, isOnSale: true, listPrice: 595 });
    expect(info?.wasPrice).toBe('AUD 595.00');
    expect(info?.price).toBe('AUD 450.00');
  });

  // AC2: no sale — wasPrice is absent
  test('returns undefined wasPrice when isOnSale is false', () => {
    const info = mapSale({ currentPrice: 595, isOnSale: false, listPrice: 595 });
    expect(info?.wasPrice).toBeUndefined();
  });

  // AC2: standard product (no priceData sale fields) — wasPrice is absent
  test('returns undefined wasPrice when isOnSale is absent', () => {
    const info = mapSale({ currentPrice: 595 });
    expect(info?.wasPrice).toBeUndefined();
  });

  // AC4: sale expired — listPrice removed or equal to currentPrice, isOnSale becomes false
  test('returns undefined wasPrice when isOnSale is true but listPrice is absent', () => {
    // BM can mark isOnSale:true but provide no listPrice; the atom must not render "Was undefined"
    const info = mapSale({ currentPrice: 450, isOnSale: true, listPrice: undefined });
    expect(info?.wasPrice).toBeUndefined();
  });

  // isRange guard: colour-only selection where sizes have different sale prices
  test('returns undefined wasPrice when isRange is true even if isOnSale and listPrice are present', () => {
    // currentPrice is the cheapest variant's price — not a definite settled figure.
    // Showing "Was $795 Now $595" would misrepresent the full colourway's pricing.
    const info = mapSale({ currentPrice: 595, isOnSale: true, listPrice: 795, isRange: true });
    expect(info?.wasPrice).toBeUndefined();
    // The selling price itself is still shown — only the Was/Now pair is suppressed.
    expect(info?.price).toBe('AUD 595.00');
  });

  // AC5: sale flagged but currentPrice absent — wasPrice must not appear without a paired Now
  test('returns undefined wasPrice when isOnSale and listPrice are present but currentPrice is absent', () => {
    // getPriceData (external, untyped) can return isOnSale:true with no currentPrice in edge
    // cases. Without this guard the mapper would emit wasPrice without a matching price, and
    // any future consumer that doesn't also check currentPrice would render "Was $595" alone.
    const info = mapSale({ isOnSale: true, listPrice: 595, currentPrice: undefined });
    expect(info?.wasPrice).toBeUndefined();
    // price itself is also absent — confirmed by the existing absent-price test above
    expect(info?.price).toBe('');
  });

  test('returns wasPrice when isRange is false (definite single-variant price)', () => {
    const info = mapSale({ currentPrice: 595, isOnSale: true, listPrice: 795, isRange: false });
    expect(info?.wasPrice).toBe('AUD 795.00');
  });

  // Formatter is called for wasPrice with the same currency as price
  test('formats wasPrice with the same injected formatter and currency as price', () => {
    const spy = vi.fn((amount: number, currency: string) => `${currency}${amount}`);
    selectPdpProductInfo(FULL, { currentPrice: 450, isOnSale: true, listPrice: 595 }, 'AUD', spy);
    expect(spy).toHaveBeenCalledTimes(2);
    expect(spy).toHaveBeenCalledWith(595, 'AUD');
  });
});

// ---------------------------------------------------------------------------
// SFCC-708 — buildRelatedSwatches
// ---------------------------------------------------------------------------

const urlBuilder = ({ id }: { id: string }) => `/product/${id}`;
const COLOUR_ATTR = 'color';

const swatch = (over: Partial<RelatedSwatch> = {}): RelatedSwatch => ({
  masterProductID: 'MASTER-001',
  colourValue: 'IVORY',
  displayName: 'Ivory',
  swatchImageURL: 'https://example.test/swatch.jpg',
  ...over,
});

describe('buildRelatedSwatches — field mapping', () => {
  test('maps displayName → name, swatchImageURL → imageUrl, masterProductID → value', () => {
    const [result] = buildRelatedSwatches(
      [swatch({ masterProductID: 'MASTER-002', displayName: 'Bay Blue', swatchImageURL: 'https://example.test/navy.jpg' })],
      urlBuilder,
      COLOUR_ATTR,
    );
    expect(result.name).toBe('Bay Blue');
    expect(result.imageUrl).toBe('https://example.test/navy.jpg');
    expect(result.value).toBe('MASTER-002');
  });

  test('sets orderable: true and forceReload: true on every entry', () => {
    const [result] = buildRelatedSwatches([swatch()], urlBuilder, COLOUR_ATTR);
    expect(result.orderable).toBe(true);
    expect(result.forceReload).toBe(true);
  });
});

describe('buildRelatedSwatches — href construction', () => {
  test('builds href as /product/{id}?{colourAttrId}={encodedColourValue}', () => {
    const [result] = buildRelatedSwatches(
      [swatch({ masterProductID: 'MASTER-001', colourValue: 'IVORY' })],
      urlBuilder,
      COLOUR_ATTR,
    );
    expect(result.href).toBe('/product/MASTER-001?color=IVORY');
  });

  test('percent-encodes colourValues containing spaces or special characters', () => {
    const [result] = buildRelatedSwatches(
      [swatch({ colourValue: 'IVORY BEIGE' })],
      urlBuilder,
      COLOUR_ATTR,
    );
    expect(result.href).toContain('color=IVORY%20BEIGE');
  });

  test('delegates base URL construction to the injected urlBuilder', () => {
    const customBuilder = vi.fn(({ id }: { id: string }) => `/custom/${id}`);
    const [result] = buildRelatedSwatches([swatch({ masterProductID: 'MASTER-003' })], customBuilder, COLOUR_ATTR);
    expect(customBuilder).toHaveBeenCalledWith({ id: 'MASTER-003' });
    expect(result.href).toContain('/custom/MASTER-003');
  });
});

describe('buildRelatedSwatches — edge cases', () => {
  test('returns an empty array when rawSwatches is empty', () => {
    expect(buildRelatedSwatches([], urlBuilder, COLOUR_ATTR)).toHaveLength(0);
  });

  test('maps multiple items preserving order', () => {
    const results = buildRelatedSwatches(
      [swatch({ masterProductID: 'A' }), swatch({ masterProductID: 'B' }), swatch({ masterProductID: 'C' })],
      urlBuilder,
      COLOUR_ATTR,
    );
    expect(results.map((r) => r.value)).toEqual(['A', 'B', 'C']);
  });
});

